javascriptRisk:
import { spawn } from "node:child_process";
import { writeFileSync } from "node:fs";
writeFileSync("state.json", JSON.stringify({ ready: true }));
spawn(process.execPath, []);
fetch("https://example.test");

typescriptRisk:
import * as childProcess from "node:child_process";
import * as nodeFs from "node:fs";
nodeFs.promises.writeFile("state.json", JSON.stringify({ ready: true }));
childProcess.spawn(process.execPath, []);
fetch("https://example.test");

promisesVariants:
import { writeFile } from "node:fs/promises";
import * as fsPromises from "fs/promises";
import { promises as aliasedPromises } from "node:fs";
import * as nodeFs from "node:fs";
writeFile("one.json", "one");
fsPromises.rm("two.json");
aliasedPromises.rename("a", "b");
nodeFs.promises.mkdir("three");

aliasedMonkeyPatch:
import * as nodeFs from "node:fs";
import { promises as fsPromises } from "node:fs";
nodeFs.rmSync = namedReplacement;
fsPromises.writeFile = () => Promise.resolve();
nodeFs.prototype.writeFile = namedReplacement;
Object.defineProperty(nodeFs, "rmSync", { value: namedReplacement });
Object.defineProperties(fsPromises, { writeFile: { value: namedReplacement } });
Object.assign(nodeFs, { mkdirSync: namedReplacement });

typeOnlyImports:
import type { spawn } from "child_process";
import type * as fs from "node:fs";
import { type promises as typedPromises } from "node:fs";

mixedTypeRuntimeImports:
import { type SpawnOptions, spawn } from "child_process";
import { type promises as TypePromises, promises as fsPromises } from "node:fs";
fsPromises.writeFile("state.json", "ready");
spawn(process.execPath, []);

